def lpHaarLevelTrace (d : ∀ n, Fin (2 ^ n) → 𝕜) (n : ℕ) (s : Set ℝ) : 𝕜 :=
  ∑ k : Fin (2 ^ n),
    ((volume.restrict (Icc (0 : ℝ) 1)).real (s ∩ lpHaarCell n k) : 𝕜) * d n k

